import sys

def min_moves_to_regular(s):
    moves = 0
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            moves += 1
            balance += 1  # We move one '(' from later, balance gets back to 0
    return moves

def solve() -> None:
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    index = 1
    for _ in range(t):
        n = int(data[index])
        s = data[index + 1]
        index += 2
        print(min_moves_to_regular(s))

if __name__ == "__main__":
    solve()
"}

