while True:
    line = input().strip()
    if not line:
        continue
    n, m = map(int, line.split())
    if n == 0 and m == 0:
        break

    rules = []
    for rule_idx in range(n):
        parts = input().split()
        while '' in parts:
            parts.remove('')
        if len(parts) != 3:
            continue
        keyword, src_pattern, dst_pattern = parts
        rules.append((keyword, src_pattern, dst_pattern))

    legal_packets = []

    for packet_idx in range(m):
        parts = input().split()
        while '' in parts:
            parts.remove('')
        if len(parts) != 3:
            continue
        src, dst, message = parts

        # Check if this packet matches any rule
        matched_rule = None
        for rule_idx in range(len(rules) - 1, -1, -1):
            keyword, src_pattern, dst_pattern = rules[rule_idx]

            # Check if source matches
            src_match = True
            for p in range(8):
                if src[p] != src_pattern[p] and src_pattern[p] != '?':
                    src_match = False
                    break

            # Check if destination matches
            dst_match = True
            for p in range(8):
                if dst[p] != dst_pattern[p] and dst_pattern[p] != '?':
                    dst_match = False
                    break

            if src_match and dst_match:
                matched_rule = rule_idx
                break

        if matched_rule is not None and rules[matched_rule][0] == 'permit':
            legal_packets.append((packet_idx, src, dst, message))

    print(len(legal_packets))
    for _, src, dst, message in legal_packets:
        print(f"{src} {dst} {message}")
"}

