MOD = 1000000007

s = input().strip()

# dp[i] = number of ways to form the first i characters
# dp[0] = 1 (empty string)
dp = [0] * (len(s) + 1)
dp[0] = 1

for i in range(1, len(s) + 1):
    dp[i] = dp[i-1]  # treat current character as a single character

    # check if we can treat two consecutive characters as 'w' (uu) or 'm' (nn)
    if i > 1:
        if s[i-1] == 'u' and s[i-2] == 'u':
            dp[i] = (dp[i] + dp[i-2]) % MOD
        if s[i-1] == 'n' and s[i-2] == 'n':
            dp[i] = (dp[i] + dp[i-2]) % MOD

    # if we see 'w' or 'm' in the result, it's impossible
    if s[i-1] in ('w', 'm'):
        dp[i] = 0

print(dp[len(s)])
"}

