def solve():
    n = int(input())
    petals = list(map(int, input().split()))

    # Find the maximum odd sum
    max_sum = 0

    # If there are no petals, we can't make any bouquet
    if all(p == 0 for p in petals):
        print(":(")
        return

    # Try all subsets
    for mask in range(1, 1 << n):
        current_sum = 0
        for i in range(n):
            if mask & (1 << i):
                current_sum += petals[i]

        # Check if this sum is valid and we found a larger valid sum
        if current_sum > 0 and current_sum < 100 and current_sum % 2 == 1:
            max_sum = max(max_sum, current_sum)

    print(max_sum if max_sum > 0 else ":(")

solve()
