    # Track achievable sums with counts of roses used
    dp = [-1] * 100
    dp[0] = 0

    for p in petals:
        # Try to update all achievable sums
        for i in range(100):
            if dp[i] != -1 and i + p < 100:
                dp[i + p] = max(dp[i + p], dp[i] + 1)

    # Find the maximum odd sum
    max_odd = 0
    for i in range(99, 0, -2):
        if dp[i] != -1:
            max_odd = i
            break

    print(max_odd if max_odd > 0 else ":(")

solve()
