import sys

def classify_word(word):
    """Classify a word into type and gender."""
    if word.endswith("lios"):
        return "adjective", "masculine"
    elif word.endswith("liala"):
        return "adjective", "feminine"
    elif word.endswith("etr"):
        return "noun", "masculine"
    elif word.endswith("etra"):
        return "noun", "feminine"
    elif word.endswith("initis"):
        return "verb", "masculine"
    elif word.endswith("inites"):
        return "verb", "feminine"
    else:
        return None, None

def solve():
    words = sys.stdin.read().split()
    n = len(words)

    if n == 0:
        print("NO")
        return

    # Classify each word
    classifications = []
    for word in words:
        word_type, gender = classify_word(word)
        if word_type is None:
            print("NO")
            return
        classifications.append((word_type, gender))

    # Check if all words have same gender
    all_same_gender = all(gender == classifications[0][1] for _, gender in classifications)

    if n == 1:
        # Exactly one valid word, it's a sentence
        print("YES")
    else:
        # Check statement structure: adjectives + noun + verbs
        adjective_count = 0
        noun_count = 0
        verb_count = 0

        for word_type, _ in classifications:
            if word_type == "adjective":
                adjective_count += 1
            elif word_type == "noun":
                noun_count += 1
            elif word_type == "verb":
                verb_count += 1

        # Must have exactly one noun
        if noun_count != 1:
            print("NO")
            return

        # Find position of the noun
        noun_index = classifications.index(("noun", classifications[0][1]))

        # Check adjectives before noun, verbs after noun
        for i, (word_type, _) in enumerate(classifications):
            if i < noun_index and word_type != "adjective":
                print("NO")
                return
            if i > noun_index and word_type != "verb":
                print("NO")
                return

        # Check all words have same gender
        if not all_same_gender:
            print("NO")
            return

        print("YES")

if __name__ == "__main__":
    solve()
"}

