import sys

def matches(pattern, address):
    """Check if pattern matches address"""
    return all(pattern[i] == '?' or pattern[i] == address[i] for i in range(8))

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        n, m = map(int, line.strip().split())

        if n == 0 and m == 0:
            break

        # Read rules
        rules = []
        for i in range(n):
            parts = sys.stdin.readline().strip().split()
            action = parts[0]
            source_pattern = parts[1]
            dest_pattern = parts[2]
            rules.append((action, source_pattern, dest_pattern))

        # Read packets
        packets = []
        for j in range(m):
            parts = sys.stdin.readline().strip().split()
            source_address = parts[0]
            dest_address = parts[1]
            message_body = parts[2]
            packets.append((source_address, dest_address, message_body))

        # Find legal packets
        legal_packets = []
        for packet in packets:
            legal = False
            for rule in rules:
                action, source_pattern, dest_pattern = rule
                if matches(source_pattern, packet[0]) and matches(dest_pattern, packet[1]):
                    legal = (action == 'permit')
                    break
            if legal:
                legal_packets.append(packet)

        # Print results
        print(len(legal_packets))
        for packet in legal_packets:
            print(f"{packet[0]} {packet[1]} {packet[2]}")

if __name__ == "__main__":
    main()
