def gcd(x, y):
    while y:
        x, y = y, x % y
    return x


def get_divisors(n):
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)


def solve():
    a, b = map(int, input().split())
    queries = []

    n = int(input())
    for _ in range(n):
        low, high = map(int, input().split())
        queries.append((low, high))

    g = gcd(a, b)

    # Get all divisors of GCD(a, b)
    divisors = get_divisors(g)

    # Process each query
    for low, high in queries:
        result = -1
        for d in divisors:
            if low <= d <= high:
                result = d
        print(result)

solve()
