# A perfect number has digit sum equal to 10
# We need to find the k-th smallest perfect number

# Direct counting approach:
# For a number with 'length' digits, we need:
# - First digit d1 (1-9), then the remaining digits sum to 10-d1
# 
# Count how many perfect numbers exist with exactly 'length' digits

def count_perfect_numbers_with_length(length):
    # dp[len][sum] = number of ways to get sum with len digits
    dp = [0] * 11  # sum from 0 to 10
    dp[0] = 1

    for i in range(length - 1):
        for s in range(10, -1, -1):
            for d in range(10):
                if s + d <= 10:
                    dp[s + d] += dp[s]

    return dp[10]

# Find the k-th perfect number directly
# Start with the smallest possible length
length = 1
while True:
    cnt = count_perfect_numbers_with_length(length)
    if k <= cnt:
        break
    k -= cnt
    length += 1

# Now we know the k-th perfect number has 'length' digits
# Let's construct it digit by digit

num = 0
for i in range(length):
    if i == 0:
        # First digit must be non-zero
        for d in range(1, 10):
            # Count how many perfect numbers start with this digit
            remaining_sum = 10 - d
            remaining_length = length - 1

            # Count ways to get remaining_sum with remaining_length digits
            dp = [0] * (remaining_sum + 1)
            dp[0] = 1

            for j in range(remaining_length):
                for s in range(remaining_sum, -1, -1):
                    for dd in range(10):
                        if s + dd <= remaining_sum:
                            dp[s + dd] += dp[s]

            if k <= dp[remaining_sum]:
                num = num * 10 + d
                k -= dp[remaining_sum]
                break
    else:
        # Subsequent digits can be 0-9
        for d in range(0, 10):
            # Count how many perfect numbers have this digit at this position
            # This is complex - let's use a simpler approach
            # Try to find the next perfect number
            # Actually, we can just count by fixing this digit and counting

            # We need to count how many perfect numbers have this prefix
            if i == 0:
                start = 0
            else:
                start = num

            # Try to find the k-th perfect number with this prefix
            temp = start * 10 + d
            temp_count = 0

            while True:
                # Count sum of digits
                s = 0
                tmp = temp

                while tmp > 0:
                    s += tmp % 10
                    tmp //= 10

                if s == 10:
                    temp_count += 1
                    if temp_count == k:
                        num = temp
                        break

                if temp >= 10000000000:
                    break
                temp += 10

