import sys

def is_prime(num):
    """Check if a number is prime using trial division"""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def find_starting_point(n):
    """Find the smallest starting point for n consecutive composite numbers"""
    for x in range(1, 100000):
        all_composite = True
        for i in range(n):
            if is_prime(x + i):
                all_composite = False
                break
        if all_composite:
            return x

def find_divisor(num):
    """Find any non-trivial divisor of a composite number"""
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return i
    # If we didn't find a divisor, the number must be prime (which shouldn't happen)
    return 2

# Read input
n = int(sys.stdin.readline())

# Find the starting point
starting_point = find_starting_point(n)

# Output the starting point
print(starting_point)

# Find and output divisors for each number in the sequence
for i in range(n):
    num = starting_point + i
    divisor = find_divisor(num)
    print(divisor)
