def solve():
    n = int(input())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, input().split())))

    # DP for forward path from (0,0) to (n-1,n-1)
    dp = [[0]*n for _ in range(n)]

    # Initialize start cell (0,0) and diagonal cells
    # We can only use diagonal cells if they are start/end
    if n > 1:
        for i in range(n):
            if i != n-1 or i != n-1:
                dp[i][i] = 0  # Not used
    dp[0][0] = grid[0][0]

    # Fill DP table
    for r in range(n):
        for c in range(n):
            if r == 0 and c == 0:
                continue

            # Only update if we stay on or above the diagonal
            if r > c:
                continue

            if r > 0 and r <= c:
                dp[r][c] = max(dp[r-1][c], dp[r][c-1])
            if r <= c:
                dp[r][c] += grid[r][c]

    # DP for return path from (n-1,n-1) to (0,0)
    dp2 = [[0]*n for _ in range(n)]

    # Initialize end cell (n-1,n-1)
    dp2[n-1][n-1] = grid[n-1][n-1]

    # Fill DP table for reverse path
    for r in range(n-1, -1, -1):
        for c in range(n-1, -1, -1):
            if r == n-1 and c == n-1:
                continue

            # Only update if we stay on or below the diagonal
            if r < c:
                continue

            if c < n-1 and r >= c:
                dp2[r][c] = max(dp2[r+1][c], dp2[r][c+1])
            if r >= c:
                dp2[r][c] += grid[r][c]

    # Total maximum gold
    max_gold = dp[n-1][n-1] + dp2[n-1][n-1] - grid[0][0] - grid[n-1][n-1]
    print(max_gold)

solve()
