def count_substrings(n, strings):
    substrings_map = {}

    # Preprocess all strings to find which substrings they contain
    for i, s in enumerate(strings):
        substrings = set()
        for length in range(1, 11):
            # Generate all substrings of current length
            for start in range(len(s) - length + 1):
                substr = s[start:start+length]
                substrings.add(substr)

        # Store which substrings this string contains
        for substr in substrings:
            if substr not in substrings_map:
                substrings_map[substr] = []
            substrings_map[substr].append(i + 1)  # 1-indexed

    return substrings_map

def answer_queries(Q, queries, substrings_map):
    results = []

    for L, R, str_query in queries:
        if str_query not in substrings_map:
            results.append(0)
        else:
            indices = substrings_map[str_query]
            # Use binary search to count how many indices are in [L, R]
            count = 0
            for idx in indices:
                if L <= idx <= R:
                    count += 1
            results.append(count)

    return results

def main():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    n = int(next(data))
    strings = [next(data).strip() for _ in range(n)]

    substrings_map = count_substrings(n, strings)

    Q = int(next(data))
    queries = []
    for _ in range(Q):
        L = int(next(data))
        R = int(next(data))
        str_q = next(data).strip()
        queries.append((L, R, str_q))

    results = answer_queries(Q, queries, substrings_map)

    print("\n".join(map(str, results)))

if __name__ == "__main__":
    main()
