def get_cells(segment: tuple[int, int, int, int]) -> tuple[int, int, int]:
    """Return (is_horizontal, start, end) for a segment"""
    x1, y1, x2, y2 = segment
    if x1 == x2:  # vertical segment
        return (0, y1, y2)  # (0 means vertical, y1, y2 are bounds)
    else:  # horizontal segment
        return (1, x1, x2)  # (1 means horizontal, x1, x2 are bounds)

# Read input
n = int(input())
horizontal_segments = []
vertical_segments = []
for _ in range(n):
    x1, y1, x2, y2 = map(int, input().split())
    is_horizontal, start, end = get_cells((x1, y1, x2, y2))
    if is_horizontal:
        horizontal_segments.append((start, end))
    else:
        vertical_segments.append((start, end))

# Count distinct cells
cells = 0
# Count horizontal cells (in rows)
for x1, x2 in horizontal_segments:
    cells += max(0, x2 - x1 + 1)

# Count vertical cells (in columns)
for y1, y2 in vertical_segments:
    cells += max(0, y2 - y1 + 1)

# Count overlaps (where rows and columns intersect)
for x1, x2 in horizontal_segments:
    for y1, y2 in vertical_segments:
        # Intersection area = (x2 - x1 + 1) * (y2 - y1 + 1) cells
        overlap = max(0, x2 - x1 + 1) * max(0, y2 - y1 + 1)
        cells -= overlap

print(cells)
