import sys

def count_distinct_subsequences(s, length):
    """Count the number of distinct subsequences of a given length"""
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # dp[i][j] = number of distinct subsequences using first i characters of s and of length j
    for i in range(1, n + 1):
        dp[i][0] = 1  # empty subsequence
        for j in range(1, length + 1):
            if j > i:
                continue
            dp[i][j] = dp[i-1][j]  # don't take s[i-1]
            # take s[i-1] and add it to subsequences that don't contain this character
            dp[i][j] += dp[i-1][j-1]

    return dp[n][length]

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    s = data[2]

    total_cost = 0
    remaining_k = k

    # We want to take subsequences starting from the longest possible length
    for l in range(n, 0, -1):
        count = count_distinct_subsequences(s, l)

        if count == 0:
            continue

        if remaining_k >= count:
            total_cost += count * (n - l)
            remaining_k -= count
        elif remaining_k > 0:
            total_cost += remaining_k * (n - l)
            remaining_k = 0
            break

    if remaining_k > 0:
        total_cost += remaining_k * n
        print(total_cost)
    else:
        print(total_cost)

if __name__ == "__main__":
    solve()
