    n = int(input())
    voters = []
    for i in range(n):
        m, p = map(int, input().split())
        voters.append((m, p, i))

    # Sort by p_i (cost) to get cheapest voters first
    voters.sort(key=lambda x: x[1])

    # Set of voters who have already voted
    voted = set()

    # Min-heap to track available voters (sorted by cost)
    heap = []

    # Initially, we have no voters

    total_cost = 0

    while len(voted) < n:
        # First, add all voters whose m_i <= number of voters already voted
        while True:
            added = False
            for i, (m, p, idx) in enumerate(voters):
                if idx not in voted and m <= len(voted):
                    voted.add(idx)
                    added = True
            if not added:
                break

        # If we've added everyone, stop
        if len(voted) >= n:
            break

        # Otherwise, we need to buy the cheapest available voter
        # Find the cheapest voter we haven't bought
        cheapest_index = -1
        cheapest_cost = float('inf')
        for i, (m, p, idx) in enumerate(voters):
            if idx not in voted and idx not in heap:
                if p < cheapest_cost:
                    cheapest_cost = p
                    cheapest_index = i

        # Add the cheapest voter (they vote for free now)
        voted.add(cheapest_index)
