    answers = data[1:]

    # Find all occupied cells
    occupied = set()
    ptr = 0

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            ans = int(answers[ptr])
            ptr += 1
            if ans == 1:
                occupied.add((i, j))

    # Find head and tail
    degrees = {}
    for cell in occupied:
        count = 0
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            neighbor = (cell[0] + dx, cell[1] + dy)
            if neighbor in occupied:
                count += 1
        degrees[cell] = count

    # Find cells with degree 1
    degree_1 = [k for k, v in degrees.items() if v == 1]

