valid = True
parts = []
genders = []

for word in words:
    # Check if word is valid and determine its type and gender
    if word.endswith("lios"):
        parts.append("adjective")
        genders.append("masculine")
    elif word.endswith("liala"):
        parts.append("adjective")
        genders.append("feminine")
    elif word.endswith("etr"):
        parts.append("noun")
        genders.append("masculine")
    elif word.endswith("etra"):
        parts.append("noun")
        genders.append("feminine")
    elif word.endswith("initis"):
        parts.append("verb")
        genders.append("masculine")
    elif word.endswith("inites"):
        parts.append("verb")
        genders.append("feminine")
    else:
        valid = False
        break

if not valid:
    print("NO")
elif len(words) == 1:
    print("YES")
else:
    # Check all words have the same gender
    gender = genders[0]
    for g in genders:
        if g != gender:
            print("NO")
            break
    else:
        # Check order: adjectives -> noun -> verbs
        # Find the noun
        noun_index = -1
        for i, part in enumerate(parts):
            if part == "noun":
                noun_index = i
                break

        if noun_index == -1:
            # No noun found
            print("NO")
        else:
            # Check all before noun are adjectives
            for i in range(noun_index):
                if parts[i] != "adjective":
                    print("NO")
                    break
            else:
                # Check all after noun are verbs
                for i in range(noun_index + 1, len(parts)):
                    if parts[i] != "verb":
                        print("NO")
                        break
                else:
                    print("YES")
