import sys

def solve(n):

    # Try different patterns based on parity
    if n % 2 == 0:
        # Even n
        if n - 1 is prime:
            # One vertex with degree n-1 (which is prime)
            # Other n-1 vertices with degree 2
            # Sum = (n-1) + 2*(n-1) = 3(n-1)
            # m = 3(n-1)/2, must be integer and prime
            if 3 * (n - 1) % 2 == 0:
                m = 3 * (n - 1) // 2
                if is_prime(m):
                    degrees = [n-1] + [2] * (n-1)

                    # Construct edges
                    edges = []

                    # Connect vertex 1 to vertex 2, 3, ..., n
                    for i in range(2, n + 1):
                        edges.append((1, i))

                    # For vertex 2, connect it to vertex 3, 4, ..., n (excluding 1)
                    for i in range(3, n + 1):
                        edges.append((2, i))

                    return m, edges

        # Try another pattern: n/2 vertices with degree 3, n/2 with degree 2
        # Sum = 5n/2, m = 5n/4, must be integer and prime
        if n % 4 == 0:
            m = 5 * n // 4
            if is_prime(m):
                degrees = [3] * (n // 2) + [2] * (n // 2)

                # Construct edges
                edges = []

                # Create a complete graph on the first n/2 vertices
                for i in range(1, n // 2 + 1):
                    for j in range(i + 1, n // 2 + 1):
                        edges.append((i, j))

                # Create a complete graph on the second n/2 vertices
                for i in range(n // 2 + 1, n + 1):
                    for j in range(i + 1, n + 1):
                        edges.append((i, j))

                return m, edges

    else:
        # Odd n
        # (n+1)/2 vertices with degree 2, one vertex with degree 3
        # Sum = 2*((n+1)/2) + 3 = n + 5
        # m = (n + 5)/2, must be integer and prime
        if (n + 5) % 2 == 0:
            m = (n + 5) // 2
            if is_prime(m):
                degrees = [3] + [2] * (n // 2)

                # Construct edges
                edges = []

                # Connect vertex 1 to vertex 2, 3, ..., n
                for i in range(2, n + 1):
                    edges.append((1, i))

                # Connect vertex 2 to vertex 3, 4, ..., n (excluding 1)
                for i in range(3, n + 1):
                    edges.append((2, i))

                return m, edges

    # If no pattern works, return -1
    return -1, None


def is_prime(x):
    if x <= 1:
        return False
    if x == 2:
        return True
    if x % 2 == 0:
        return False
    for i in range(3, int(x**0.5) + 1, 2):
        if x % i == 0:
            return False
    return True

n = int(sys.stdin.readline())
