        if part:
            coeff_sign = 1 if part[0] == '+' else -1
            coeff_str = part[1:] if part else ''
        else:
            coeff_sign = 1
            coeff_str = ''

        # Parse coefficient
        if coeff_str:
            coeff = int(coeff_str)
        else:
            coeff = 1

        # Determine if it's '++a' or 'a++'
        if part and part[0] == '+' and i > 0:
            if len(part) > 1 and part[1] == '+':
                # '++a' (two pluses before a)
                summands.append((coeff * coeff_sign, '++a'))
