def solve():
    n = int(input())
    cards = list(map(int, input().split()))

    max_length = 0

    # Try different base counts k
    for k in range(0, 10):  # k can be from 0 to 9

        # Try all possible distributions of counts
        # Each count can be k or k+1
        # The sum should be ≤ n

        # We need to try different numbers of numbers that have count k+1
        # The numbers that have count k+1 can be any subset of {1, 2, ..., 8}

        # Try all possible subsets
        for mask in range(1 << 8):
            # For each bit, if set, that number has count k+1, else k
            total = 0
            for i in range(1, 9):
                if mask & (1 << (i-1)):
                    total = k + 1
                else:
                    total = k
                if total > n:
                    break
            if total > n:
                continue

            # Now we need to check if we can select cards with these counts
            # and satisfy the continuity condition

            # First, count occurrences of each number
            freq = [0] * 9
            for i in range(n):
                freq[cards[i]] += 1

            # For each number, we can select at most min(freq[i], k+1) cards
            # (if the number has count k+1 in this distribution)
            selected_count = [0] * 9
            card_indices = [[] for _ in range(9)]
            for i, val in enumerate(cards):
                card_indices[val].append(i)

            # Select cards greedily
            for i in range(1, 9):
                if mask & (1 << (i-1)):
                    needed = min(k + 1, freq[i])
                else:
                    needed = min(k, freq[i])
                if needed <= 0:
                    continue

                # Select needed cards of this value from the contiguous segment
                for j in range(needed):
                    idx = card_indices[i][j]
                    if not selected[idx]:
                        selected[idx] = True
                        selected_count[i] = needed

            # Check if we used all needed cards
            valid = True
            for i in range(1, 9):
                if mask & (1 << (i-1)):
                    needed = min(k + 1, freq[i])
                else:
                    needed = min(k, freq[i])
                if needed > 0 and selected_count[i] < needed:
                    valid = False
                    break

            if not valid:
                continue

            # Check continuity condition
            for i in range(1, 9):
                indices = [idx for idx in range(n) if selected[idx] and cards[idx] == i]
                if not indices:
                    continue

                # Check if indices form a continuous segment
                min_idx = min(indices)
                max_idx = max(indices)
                if max_idx - min_idx + 1 != len(indices):
                    valid = False
                    break

            if valid:
                max_length = max(max_length, sum(selected))

    print(max_length)

