# Grammar rules:
# E ::= T | E '+' T
# T ::= F | T '*' F
# F ::= '1' | '2' | '3' | '4' | '5' | '6' | '7' | '8' | '9' | '(' E ')'

# We need to count substrings that form valid expressions equal to target n

# Use dynamic programming to count valid substrings equal to n
# Let dp[i][j][v] = number of substrings ending at i, starting at j with value v
# But we need to be careful about operator precedence and parentheses

# Instead, we'll trace through the string and evaluate expressions

# Parse the string into tokens
# Then use a recursive approach to evaluate expressions

# Function to evaluate an expression from start to end with parentheses tracking
def evaluate(s, i, j, paren_count):
    if i > j:
        return []  # Empty string

    # Try to parse as a digit
    if s[i] in '123456789':
        if i + 1 > j:
            return []  # Only one digit
        if s[i+1] == '+':
            # Try E '+' T
            # But need to check if we can parse the rest
            # Actually, E is either T or E '+' T
            # So we need to find all T substrings and then '+'
            # This approach is too vague

            # Better: Try to find all valid expressions and their values recursively

            # Check if T starts at i
            t_values = evaluate_T(s, i, j, paren_count)
            for t_val in t_values:
                if j < len(s) and s[j] == '+':
                    # We've found a '+' at the end, so E is before '+'
                    e_values = evaluate_E(s, i, j-1, paren_count)
                    for e_val in e_values:
                        yield e_val
                        yield (e_val + t_val)  # E '+' T = E + T

            return []

        elif s[i+1] == '*':
            # Try T '*' F
            # T at i, then '*' at i+1, then F at i+2
            if i+2 <= j:
                t_values = evaluate_T(s, i, i, paren_count)
                f_values = evaluate_F(s, i+2, j, paren_count)
                for t_val in t_values:
                    for f_val in f_values:
                        yield t_val * f_val

        return []

    # Try to parse as '(' E ')'
    elif s[i] == '(' and j - i + 1 >= 3 and s[j] == ')':
        # Need to check if there's an E inside
        if i + 1 <= j - 1:
            # Check if we can parse E inside
            e_values = evaluate_E(s, i+1, j-1, paren_count + 1)
            for e_val in e_values:
                yield e_val

    return []

def evaluate_T(s, i, j, paren_count):
    if paren_count < 0:
        return []  # Unmatched parentheses
    if i > j:
        return []  # Empty string

    # T ::= F | T '*' F
    # First try to parse as F
    if s[i] in '123456789':
        if i + 1 > j:
            yield int(s[i])
        elif s[i+1] == '+':
            yield int(s[i])
        elif s[i+1] == '*':
            yield int(s[i])
        else:
            yield int(s[i])
    elif s[i] == '(' and j - i + 1 >= 3 and s[j] == ')':
        e_values = evaluate_E(s, i+1, j-1, paren_count + 1)
        for e_val in e_values:
            yield e_val

    # Then try to parse as T '*' F
    if s[i] in '123456789':
        if i + 1 <= j and s[i+1] == '*':
            # F starts at i+2
            if i+2 <= j:
                f_values = evaluate_F(s, i+2, j, paren_count)
                for f_val in f_values:
