    elif s[i] == '(' and j - i + 1 >= 3 and s[j] == ')' and i + 1 <= j - 1:
        e_values = evaluate_E(s, i+1, j-1, paren_count + 1)
        for e_val in e_values:
            # Now try to parse as T '*' F
            if s[i+1] == '*' and i+2 <= j - 1:
                if s[i+2] in '123456789':
                    yield e_val * int(s[i+2])
                elif s[i+2] == '(' and j - i + 3 >= 5 and s[i+3] == '*' and s[j] == ')':
                    # F is another (E)
                    f_values = evaluate_E(s, i+4, j-1, paren_count + 2)
                    for f_val in f_values:
