def solve():
    n = int(input())
    x = list(map(int, input().split()))

    # Sort boxes by strength
    x.sort()

    stacks = []  # list of stack heights

    for strength in x:
        # Find the tallest stack that can support this box
        # A box with strength s can support at most s boxes above it
        # So it needs a stack of height ≤ s + 1 (including itself)
        # We want to place it on the tallest such stack

        # Find the tallest stack with height ≤ strength + 1
        best = None
        for h in stacks:
            if h <= strength + 1:
                if best is None or h > best:
                    best = h

        if best is not None:
            # Place on top of that stack
            index = stacks.index(best)
            stacks[index] += 1
        else:
            # Create a new stack of height 1 (this box as the bottom)
            stacks.append(1)

    print(len(stacks))

if __name__ == "__main__":
    solve()
