def main():
    # Read the first line as n
    line = input().strip()
    if not line:
        return
    n = int(line)

    # Read the next n lines as rows
    matrix = []
    for _ in range(n):
        row = list(map(int, input().split()))
        matrix.append(row)

    # Find path from (0,0) to (n-1,n-1)
    # Use dynamic programming for maximum gold

    # Build dp table (n+1)x(n+1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill from top-left to bottom-right
    for i in range(n):
        for j in range(n):
            if i == j:
                continue  # skip diagonal
            # Can come from above or left
            dp[i+1][j+1] = matrix[i][j] + max(dp[i][j+1], dp[i+1][j])

    # Trace path
    x, y = n, n
    path = [(x, y)]

    while x > 0 or y > 0:
        if x > 0:
            # From above? Check if it's valid
            if dp[x][y] == matrix[x-1][y-1] + max(dp[x-1][y], dp[x][y-1]):
                x -= 1
        else:
            y -= 1
        path.append((x, y))

    # Sum gold
    total = 0
    for i, j in path:
        total += matrix[i-1][j-1]

    print(total)

if __name__ == "__main__":
    main()
