import sys

def solve():
    a = []
    for _ in range(3):
        row = list(map(int, sys.stdin.readline().strip().split()))
        a.append(row)

    b = [[val % 2 for val in row] for row in a]

    # compute final state
    final = [[0]*3 for _ in range(3)]

    for i in range(3):
        for j in range(3):
            toggle = b[i][j]  # itself
            if i > 0:
                toggle += b[i-1][j]
            if i < 2:
                toggle += b[i+1][j]
            if j > 0:
                toggle += b[i][j-1]
            if j < 2:
                toggle += b[i][j+1]

            final[i][j] = (1 - toggle) % 2

    for row in final:
        print(''.join(str(cell) for cell in row))

if __name__ == '__main__':
    solve()
"}

