def find_min_difference(n):
    """Find the minimum difference between length and width for n cupcakes"""
    if n == 1:
        return 0

    # Find the largest divisor of n less than or equal to sqrt(n)
    sqrt_n = int(n**0.5)

    # Check from sqrt_n down to 1
    for divisor in range(sqrt_n, 0, -1):
        if n % divisor == 0:
            return abs((n // divisor) - divisor)

    # If no divisor found (n is prime, divisor = 1)
    return n - 1

