def get_divisors(n):
    """Return a sorted list of divisors of n."""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def solve():
    a, b = map(int, input().split())
    queries = int(input())

    # Compute gcd
    g = gcd(a, b)

    # Get all divisors of gcd
    divisors = get_divisors(g)

    # Process each query
    for _ in range(queries):
        low, high = map(int, input().split())

        # Find the largest divisor in range [low, high]
        result = -1
        for d in divisors:
            if low <= d <= high:
                result = d

        print(result)

# Run the solution
