    # All characters before first 'b' should be 'a'
    for i in range(first_b):
        if s[i] != 'a':
            print("NO")
            break
    else:
        # Check that all 'b's come before all 'c's
        # Find the index of the first 'c'
        first_c = s.find('c')

        # All characters before first 'c' should be 'b'
        for i in range(first_c):
            if s[i] != 'b':
                print("NO")
                break
        else:
            # Check if the number of 'c's equals number of 'a's or 'b's
            if count_c == count_a or count_c == count_b:
