    global_min_r = min(r)

    # Sort for finding second max l and second min r
    max_l_sorted = sorted(l, reverse=True)
    min_r_sorted = sorted(r)

    # Compute second max l and second min r
    max_l_count = max_l_sorted.count(global_max_l)
    if max_l_count == 1:
        max_l2 = max_l_sorted[1] if n >= 2 else -1
    else:
        max_l2 = global_max_l

    min_r_count = min_r_sorted.count(global_min_r)
    if min_r_count == 1:
        min_r2 = min_r_sorted[1] if n >= 2 else -1
    else:
        min_r2 = global_min_r

    best_length = 0
    for i in range(n):
        li = l[i]
        ri = r[i]

        if li == global_max_l:
            if max_l_count > 1:
                new_max_l = global_max_l
            else:
                new_max_l = max_l2
        else:
            new_max_l = global_max_l

