import math

def has_non_trivial_divisor(num):
    """Check if a number has a divisor other than 1 and itself"""
    if num <= 1:
        return False
    if num <= 3:
        return num % 2 == 0  # 2 has divisor 2
    if num % 2 == 0:
        return True
    sqrt_num = int(math.isqrt(num))
    for i in range(3, sqrt_num + 1, 2):
        if num % i == 0:
            return True
    return False

def find_smallest_starting_number(n):
    """Find the smallest starting number x such that x, x+1, ..., x+n-1 are all composite"""
    i = 1
    while True:
        start = i
        valid = True
        for k in range(n):
            if not has_non_trivial_divisor(i):
                valid = False
                break
            i += 1
        if valid:
            return start

