def count_sum(X):
    mod = 10**9 + 7

    # Function to convert number string to sorted digits
    def sorted_digits(num):
        return int(''.join(sorted(num)))

    # Generate all numbers with sorted digits up to length of X
    length = len(X)
    dp = [[0] * (length + 1) for _ in range(length + 1)]

    for d in range(1, length + 1):
        # First digit from 1 to 9
        for i in range(1, 10):
            dp[d][i] = dp[d-1][i-1] + 1

        # Subsequent digits from 0 to 9
        for i in range(1, length + 1):
            for j in range(10):
                # DP[i][j] = DP[i-1][j] + DP[i-1][j-1] ?
                # Actually DP[i][j] = DP[i-1][j] + (DP[i-1][j-1] if j > 0 else 0)
                dp[i][j] = dp[i-1][j] + dp[i-1][j-1] if j > 0 else dp[i-1][j]

    result = 0
    for d in range(1, length + 1):
        for i in range(1, length + 1):
            # Count numbers with sorted digits of length i
            count = dp[i][i] - dp[i-1][i-1]
            result = (result + sorted_digits(str(count))) % mod

    return result

X = input().strip()
print(count_sum(X))
