        dp[1][0] = 1  # empty prefix
        for i in range(1, n):
            for j in range(10):
                dp[i+1][j] = dp[i][j] + (dp[i][j-1] if j > 0 else 0)

        # DP for exact match
        dp2 = [[0] * (10) for _ in range(n + 1)]
        dp2[1][0] = 1  # empty prefix

        # Process each digit
        for i in range(1, n):
            for j in range(10):
