def count_sorted_numbers(X):
    """Count numbers <= X with digits sorted in non-decreasing order"""
    mod = 10**9 + 7

    x = list(map(int, str(X)))
    n = len(x)

    # dp[i][j] = count of numbers with first i digits, last digit <= j, digits sorted
    dp = [[0] * (10) for _ in range(n + 1)]
    dp[1][0] = 1  # empty prefix

    # First digit from 1 to 9
    for i in range(1, 10):
        dp[1][i] = 1

    # DP for rest of digits
    for i in range(1, n):
        for j in range(10):
            if dp[i][j] == 0:
                continue

            # Try next digit d <= current digit
            for d in range(0, x[i] + 1):
                if d <= j:
                    dp[i+1][d] = (dp[i+1][d] + dp[i][j]) % mod

    return dp[n][9]

def solve(X):
    """Compute sum of sorted digit numbers from 1 to X"""
    X = int(X)
    mod = 10**9 + 7

    # Count numbers with sorted digits
    length = len(str(X))
    total = 0

    # Generate all numbers with sorted digits recursively
    def dfs(pos, prev, is_prefix, path, count):
        if pos == count:
            if count == 0:
                return
            if is_prefix:
                num = int(''.join(map(str, path)))
                if num <= X:
                    total = (total + num) % mod
            else:
                total = (total + num) % mod
            return

        for d in range(0 if pos > 0 else 1, 10):
            if d < prev:
                continue
            path.append(d)
            dfs(pos+1, d, is_prefix and d == int(X[len(path) - 1]), path, count)
            path.pop()

    # Iterate over all lengths
    for length in range(1, len(str(X)) + 1):
        dfs(0, 0, True, [], length)

    return total

