import sys
from collections import Counter

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    nums = list(map(int, data[1:1 + n * n]))
    total = sum(nums)
    s = total // n

    square = [[0] * n for _ in range(n)]

    # We'll use a Counter for remaining numbers
    remaining = Counter(nums)

    # Recursive backtracking with pruning
    def backtrack(pos):  # pos is (i,j) index
        i, j = pos
        if i == n:
            # All cells filled, check diagonals
            if sum(square[0]) != s:
                return False
            if sum(square[n-1]) != s:
                return False
            if sum(square[i][i] for i in range(n)) != s:
                return False
            if sum(square[i][n-1-i] for i in range(n)) != s:
                return False
            return True

        if j == n:
            # Move to next row
            return backtrack((i+1, 0))

        # Try each remaining number
        for num in list(remaining.keys()):
            # Check row and column bounds
            row_sum = sum(square[i])
            col_sum = sum(square[k][j] for k in range(n))
            if row_sum + num > s:
                continue
            if col_sum + num > s:
                continue

            # Place the number
            square[i][j] = num
            remaining[num] -= 1
            if remaining[num] == 0:
                del remaining[num]

            # Recursive
            if backtrack((i, j + 1)):
                return True

            # Backtrack
            square[i][j] = 0
            remaining[num] += 1
        return False

    if backtrack((0, 0)):
        print(s)
        for row in square:
            print(' '.join(map(str, row)))

if __name__ == '__main__':
    solve()
"}

