n, m = map(int, input().split())

# Binary search approach
# We want to find the smallest day d such that:
# Either:
# 1. The barn never becomes full: n + (d-1)m < d(d+1)/2
# 2. The barn becomes full at some point k: n - k <= 0 and d >= n

left = 1
right = 10**18

while left < right:
    mid = (left + right) // 2

    # Check if barn becomes empty on or before day mid
    # Case 1: Barn never becomes full
    total = n + (mid - 1) * m
    required = mid * (mid + 1) // 2

    if total < required:
        right = mid
    else:
        # Case 2: Barn becomes full at some point k <= mid
        # We need to find if barn becomes full before mid
        # k = 1 while n + (k-1)*m < n + k*(k+1)//2:
        k = 1
        while k < mid:
            k += 1
            if n + (k-1)*m >= n + k*(k+1)//2:
                break

        if k >= mid:
            # Barn never becomes full
            if total < required:
                right = mid
            else:
                left = mid + 1
        else:
            # Barn becomes full at k, and then we need d >= n
            if mid >= n:
                right = mid
            else:
                left = mid + 1

print(right)
