from collections import Counter

def solve():
    left = Counter(l)
    right = Counter(r)

    # Track which positions we've used
    used_left = [False] * n
    used_right = [False] * n

    # Pair left '?' with right '?', but we need to think about this differently
    # Let's just try a different greedy approach

    pairs = []

    # Pair left '?' with right '?'
    l_idx = [i for i, c in enumerate(l) if c == '?']
    r_idx = [i for i, c in enumerate(r) if c == '?']

    for l_pos, r_pos in zip(l_idx, r_idx):
        pairs.append((l_pos + 1, r_pos + 1))

    # Use remaining '?' from left with right letters
    for l_pos in l_idx[len(r_idx):]:
        for letter, count in list(right.items()):
            if count > 0:
                for r_pos in range(len(r)):
                    if not used_right[r_pos] and r[r_pos] == letter:
                        pairs.append((l_pos + 1, r_pos + 1))
                        used_right[r_pos] = True
                        right[letter] -= 1
                        break

    # Use remaining '?' from right with left letters
    for r_pos in r_idx[len(l_idx):]:
        for letter, count in list(left.items()):
            if count > 0:
                for l_pos in range(len(l)):
                    if not used_left[l_pos] and l[l_pos] == letter:
                        pairs.append((l_pos + 1, r_pos + 1))
                        used_left[l_pos] = True
                        left[letter] -= 1
                        break

    # Now handle specific letter pairings
    for letter in range(26):
        for i in range(len(l)):
            if l[i] == chr(ord('a') + letter) and not used_left[i]:
                for j in range(len(r)):
                    if r[j] == chr(ord('a') + letter) and not used_right[j]:
                        pairs.append((i + 1, j + 1))
                        used_left[i] = True
                        used_right[j] = True
                        break

    print(len(pairs))
    for a, b in pairs:
        print(a, b)

