import sys

def format_tree(lines):
    if not lines:
        return ''

    root = lines[0]
    tree = {root: []}
    node_count = 1

    # Build the tree
    for i in range(1, len(lines)):
        line = lines[i]
        indent = line.count('.')
        content = line[indent:].lstrip()

        # Find the parent node by checking all previous lines
        parent = lines[0]
        for j in range(1, i):
            if lines[j].count('.') == indent:
                parent = lines[j]
                break

        tree[parent].append((indent, content))
        node_count += 1

    # Format the tree
    result = []

    def traverse(node, indent_level):
        # Format the current node
        if indent_level == 0:
            result.append(node)
        else:
            result.append(' ' * indent_level + '+' + node)

