import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    cubes = []
    for i in range(1, n + 1):
        c = int(next(it))
        s = int(next(it))
        cubes.append((c, s, i))

    # Group by color
    color_groups = {}
    for c, s, idx in cubes:
        if c not in color_groups:
            color_groups[c] = {'sum': 0, 'indices': []}
        color_groups[c]['sum'] += s
        color_groups[c]['indices'].append(idx)

    # Find max pair
    max_sum = -1
    best_pair = None
    for i in color_groups:
        for j in color_groups:
            if i == j:
                continue
            s = color_groups[i]['sum'] + color_groups[j]['sum']
            if s > max_sum:
                max_sum = s
                best_pair = (i, j)

    # Build result by interleaving indices
    c1, c2 = best_pair
    group1 = color_groups[c1]
    group2 = color_groups[c2]

    result = []
    for i in range(max(len(group1['indices']), len(group2['indices']))):
        if i < len(group1['indices']):
            result.append(group1['indices'][i])
        if i < len(group2['indices']):
            result.append(group2['indices'][i])

    print(max_sum)
    print(len(result))
    print(' '.join(map(str, result)))

if __name__ == '__main__':
    main()
