n, m = map(int, input().split())

# Build adjacency list
graph = [[] for _ in range(n)]
edges = []

for _ in range(m):
    u, v = map(int, input().split())
    u -= 1
    v -= 1
    graph[u].append(v)
    graph[v].append(u)
    edges.append((u, v))

# Try to color the graph with 2 colors
color = [-1] * n
is_bipartite = True

to_visit = list(range(n))
visited = [False] * n

while to_visit:
    node = to_visit.pop()
    if visited[node]:
        continue

    visited[node] = True
    queue = [node]
    color[node] = 0

    while queue:
        current = queue.pop(0)
        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                color[neighbor] = color[current] ^ 1
                queue.append(neighbor)
            else:
                if color[neighbor] == color[current]:
                    is_bipartite = False
                    break
        if not is_bipartite:
            break

    if not is_bipartite:
        break

if not is_bipartite:
    print("NO")
else:
    print("YES")
    # Direct edges from one color to the other
    result = []
    for u, v in edges:
        if color[u] == 0 and color[v] == 1:
            result.append("0")
        elif color[u] == 1 and color[v] == 0:
            result.append("1")
        else:
            # This shouldn't happen in a bipartite graph
            result.append("0")
    print("".join(result))
