def solve():
    n, k = map(int, input().split())
    arr = list(map(int, input().split()))
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + arr[i]

    # dp[i][j][last_sum] = max value for first i elements, j subarrays picked, last subarray sum = last_sum
    # To keep this simple, I'll use a dictionary of dictionaries for DP
    dp = [[dict() for _ in range(k + 1)] for _ in range(n + 1)]
    dp[0][0] = {0: 0}  # dp[0][0] = (0 subarrays picked, last sum = 0, max value = 0)

    for i in range(n + 1):
        for j in range(k + 1):
            if j == 0:
                dp[i][0][0] = 0
                continue
            if not dp[i][j]:
                continue

            for l in range(i):
                if j-1 not in dp[l] or not dp[l][j-1]:
                    continue
                for prev_last_sum, prev_max in dp[l][j-1].items():
                    new_last_sum = prefix[i] - prefix[l]
                    current_value = prev_max + abs(prev_last_sum - new_last_sum)
                    if new_last_sum in dp[i][j]:
                        dp[i][j][new_last_sum] = max(dp[i][j][new_last_sum], current_value)
