                    else:
                        dp[i][j][new_last_sum] = current_value

    best = 0
    for last_sum, value in dp[n][k].items():
        if value > best:
            best = value

    print(best)

solve()

def solve():
    n, k = map(int, input().split())
    arr = list(map(int, input().split()))
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + arr[i]

    # dp[i][j]: list of (last_sum, max_value) pairs for first i elements, j subarrays picked
    dp = [[[] for _ in range(k + 1)] for _ in range(n + 1)]
    dp[0][0] = [(0, 0)]  # dp[0][0] = (0 subarrays picked, last sum = 0, max value = 0)

    for i in range(n + 1):
        for j in range(k + 1):
            if j == 0:
                dp[i][0] = [(0, 0)]
                continue
            if not dp[i][j]:
                continue

            for l in range(i):
                if j-1 not in dp[l] or not dp[l][j-1]:
                    continue
                for last_sum, value in dp[l][j-1]:
                    new_last_sum = prefix[i] - prefix[l]
                    new_value = value + abs(last_sum - new_last_sum)
                    dp[i][j].append((new_last_sum, new_value))

    best = 0
    for last_sum, value in dp[n][k]:
        if value > best:
            best = value

    print(best)

solve()

