def max_gold(N, grid):
    """Calculate the maximum gold collected from top-left to bottom-right and back."""

    # dp[i][j] stores the maximum gold collected to reach (i,j)
    dp = [[float('-inf')] * N for _ in range(N)]
    dp[0][0] = grid[0][0]

    # dp_back[i][j] stores the maximum gold collected to reach (i,j) on the way back
    dp_back = [[float('-inf')] * N for _ in range(N)]
    dp_back[N-1][N-1] = grid[N-1][N-1]

    # Fill dp from top-left to bottom-right
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue

            # From (i-1,j) if valid
            if i > 0 and j != i-1:
                if dp[i-1][j] != float('-inf'):
                    dp[i][j] = max(dp[i][j], dp[i-1][j] + grid[i][j])

            # From (i,j-1) if valid
            if j > 0 and i != j-1:
                if dp[i][j-1] != float('-inf'):
                    dp[i][j] = max(dp[i][j], dp[i][j-1] + grid[i][j])

    # Fill dp_back from bottom-right to top-left
    for i in range(N-1, -1, -1):
        for j in range(N-1, -1, -1):
            if i == N-1 and j == N-1:
                continue

            # From (i+1,j) if valid
            if i < N-1 and j != i+1:
                if dp_back[i+1][j] != float('-inf'):
                    dp_back[i][j] = max(dp_back[i][j], dp_back[i+1][j] + grid[i][j])

            # From (i,j+1) if valid
            if j < N-1 and i != j+1:
                if dp_back[i][j+1] != float('-inf'):
                    dp_back[i][j] = max(dp_back[i][j], dp_back[i][j+1] + grid[i][j])

    # The answer is dp[N-1][N-1] + dp_back[N-1][N-1] - grid[N-1][N-1]
    return dp[N-1][N-1] + dp_back[N-1][N-1] - grid[N-1][N-1]

