import sys

# Compute f(d, s): number of non-negative integer sequences of length d with sum s, each 0..9
# Use iterative DP on the fly (small values, up to 10)
def count_sequences(d, s):
    if d == 0:
        return 1 if s == 0 else 0
    # bottom-up DP
    dp = [0] * (s + 1)
    dp[0] = 1
    for i in range(d):
        new_dp = [0] * (s + 1)
        for j in range(s + 1):
            for digit in range(0, min(9, s) + 1):
                if j - digit >= 0:
                    new_dp[j] += dp[j - digit]
        dp = new_dp
    return dp[s]

def solve(k):
    # Find length L
    length = 1
    while True:
        cnt = 0
        for l in range(1, length + 1):
            cnt_l = count_sequences(l, 10) - (count_sequences(l-1, 10) if l > 1 else 0)
            cnt += cnt_l
        if cnt >= k:
            break
        length += 1

    # Now find the (k - prefix_sum)-th number within length length
    prefix_sum = 0
    for l in range(1, length):
        cnt_l = count_sequences(l, 10) - (count_sequences(l-1, 10) if l > 1 else 0)
        prefix_sum += cnt_l

    # Generate number
    remaining_sum = 10
    remaining_length = length
    number = []

    # First digit
    for d in range(1, 10):
        if d > remaining_sum:
            continue
        cnt = count_sequences(remaining_length, remaining_sum - d) - (count_sequences(remaining_length - 1, remaining_sum - d) if remaining_length > 1 else 0)
        if cnt >= k - prefix_sum:
            number.append(str(d))
            remaining_sum -= d
            remaining_length -= 1
            break
        else:
            k -= cnt

    # Subsequent digits
    while remaining_length > 0:
        for d in range(0, 10):
            if d > remaining_sum:
                continue
            cnt = count_sequences(remaining_length - 1, remaining_sum - d)
            if cnt >= k:
                number.append(str(d))
                remaining_sum -= d
                remaining_length -= 1
                break
            else:
                k -= cnt

    return int(''.join(number))

def solve_brute(k):
    count = 0
    i = 1
    while True:
        s = 0
        tmp = i
        while tmp > 0:
            s += tmp % 10
            tmp //= 10
        if s == 10:
            count += 1
        if count == k:
            return i
        i += 1

# Test
# print(solve(1))  # should be 19
# print(solve(2))  # should be 28
# print(solve(10000))  # expected 10214200

if __name__ == "__main__":
    k = int(sys.stdin.readline())
    print(solve(k))
