grid = [input().strip() for _ in range(n)]

# We need to place south magnets in certain cells
# Let's try placing south magnets at cells where we need them
# For black cells, we might need south magnets in their row or column
# For white cells, we need no south magnets in their row OR no south magnets in their column

# Try a simple strategy: place south magnets at black cells first
south_magnets = set()
for i in range(n):
    for j in range(m):
        if grid[i][j] == '#':
            south_magnets.add((i, j))

# Check if every row and column has at least one south magnet
has_row = [False] * n
has_col = [False] * m
for i, j in south_magnets:
    has_row[i] = True
    has_col[j] = True

if all(has_row) and all(has_col):
    # Check if we can reach all black cells
    # A cell (i, j) can be reached if there's a south magnet in row i
    # or there's a south magnet in column j
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#' and not (has_row[i] or has_col[j]):
                print(-1)
                exit()
    print(len(south_magnets))
else:
    print(-1)
