    """Count how many valid "()" pairs exist in s (in order)."""
    count = 0
    balance = 0
    i = 0
    while i < len(s):
        if s[i] == '(':
            balance += 1
        else:
            if balance > 0:
                count += 1
                balance -= 1
        i += 1
    return count


