def match_pattern(pattern, value):
    """Check if a value matches a pattern with '?' wildcards"""
    if len(pattern) != len(value):
        return False
    for p, v in zip(pattern, value):
        if p != '?' and p != v:
            return False
    return True


def main():
    import sys
    input_lines = sys.stdin.read().strip().splitlines()
    idx = 0
    results = []

    while idx < len(input_lines):
        line = input_lines[idx]
        n, m = map(int, line.split())
        idx += 1

        if n == 0 and m == 0:
            break

        rules = []
        for _ in range(n):
            parts = input_lines[idx].split()
            idx += 1
            if parts[0] == "permit":
                rules.append((parts[1], parts[2], "permit"))
            else:  # deny
                rules.append((parts[1], parts[2], "deny"))

        packets = []
        for _ in range(m):
            parts = input_lines[idx].split()
            idx += 1
            packets.append((parts[0], parts[1], " ".join(parts[2:])))

        legal_packets = []
        for packet in packets:
            source, dest, message = packet
            is_legal = False
            for rule in reversed(rules):  # highest priority first
                rule_source, rule_dest, rule_type = rule
                if match_pattern(rule_source, source) and match_pattern(rule_dest, dest):
                    if rule_type == "permit":
                        is_legal = True
                    else:
                        is_legal = False
                    break
            if is_legal:
                legal_packets.append(packet)

        results.append(len(legal_packets))
        results.extend(legal_packets)

    # Print results
    out = ""
    for i, result in enumerate(results):
        if i > 0:
            out += "\n"
        out += result
    print(out)

if __name__ == "__main__":
    main()
