import sys
import math

def compute_gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def find_divisors(num):
    divisors = set()
    for i in range(1, int(math.isqrt(num)) + 1):
        if num % i == 0:
            divisors.add(i)
            divisors.add(num // i)
    return sorted(divisors)

a, b = map(int, sys.stdin.readline().split())
gcd_value = compute_gcd(a, b)

divisors = find_divisors(gcd_value)

