for _ in range(n):
    low, high = map(int, sys.stdin.readline().split())

    # Binary search for the greatest divisor <= high
    left, right = 0, len(divisors) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if divisors[mid] <= high and divisors[mid] >= low:
            result = divisors[mid]
            left = mid + 1  # Try to find a larger divisor
        elif divisors[mid] < low:
            left = mid + 1
        else:  # divisors[mid] > high
            right = mid - 1

    print(result)
