def find_min_diff(N):
    """Find the minimum difference between length and width for a rectangular arrangement of N cupcakes"""
    min_diff = N - 1  # Maximum possible difference

    # Check all possible divisors up to sqrt(N)
    for i in range(1, int(N**0.5) + 1):
        if N % i == 0:
            # Found a divisor i, with corresponding divisor N//i
            diff = abs(i - N//i)
            if diff < min_diff:
                min_diff = diff

    return min_diff

